def get_max_level_of_parens(paren_string: str) -> int:
    """ Calculates max level of parentheses nesting for a given string representation of parentheses.

    E.g. (()()) has maximum two levels of nesting while ((())) has three.
    """
    n = len(paren_string)
    open_paren = 0
    max_level = 0
    for c in range(n):
        if c < n // 2:
            if c < open_paren:
                return 0
            else:
                open_paren -= 1
        elif c >= n // 2:
            if c == n // 2:
                open_paren += 1
            elif c == open_paren + 1:
                return max_level + 1
            elif c < open_paren + 1:
                return max_level + 1
            else:
                return max_level

